import{_ as a,o,c as i,e as r}from"./chunks/framework.YHAu34vx.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"04_php/100_proyecto_ia/prompt_cursor/2.md","filePath":"04_php/100_proyecto_ia/prompt_cursor/2.md"}'),l={name:"04_php/100_proyecto_ia/prompt_cursor/2.md"};function s(c,e,n,t,d,p){return o(),i("div",null,[...e[0]||(e[0]=[r("<p>Antes de comenzar la implementación, quiero modificar y confirmar algunas decisiones arquitectónicas.</p><p><strong>1. Composer y autocarga PSR-4</strong></p><ul><li>Utilizaremos Composer para gestionar la carga automática de clases.</li><li>Configura <code>composer.json</code> con autoload PSR-4.</li><li>Utiliza el namespace <code>App\\</code> asociado al directorio <code>src/</code>.</li><li>Los controladores estarán en <code>App\\Controllers</code>.</li><li>Los servicios estarán en <code>App\\Services</code>.</li><li>Utiliza <code>vendor/autoload.php</code> como punto de entrada de la autocarga.</li><li>Elimina <code>src/cargar.php</code> y la carga manual de clases mediante <code>require_once</code>.</li><li>No instales frameworks PHP ni dependencias adicionales innecesarias.</li><li>Las vistas PHP seguirán cargándose mediante <code>require</code> cuando corresponda.</li></ul><p><strong>2. Servidor de Inteligencia Artificial</strong></p><p>Mantendremos la propuesta original de utilizar Ollama como servidor de IA, en lugar de la API comercial de OpenAI.</p><ul><li>Ollama se ejecutará mediante Docker.</li><li>La aplicación PHP consumirá su API HTTP utilizando cURL.</li><li>No necesitaremos claves comerciales de OpenAI.</li><li>Utilizaremos inicialmente un modelo pequeño, adecuado para pruebas docentes.</li><li>La URL de Ollama y el modelo serán configurables.</li><li>La comunicación entre PHP y Ollama se realizará mediante la red interna de Docker.</li><li>No expondremos públicamente la API de Ollama.</li></ul><p><strong>3. Organización del código</strong></p><p>Mantén la separación entre controladores, servicios, vistas y configuración.</p><p>Quiero utilizar clases, funciones y arrays, pero sin introducir patrones de diseño innecesarios.</p><p>Las variables, métodos y funciones estarán nombrados en castellano, utilizando <code>camelCase</code> para los métodos y variables, y <code>PascalCase</code> para las clases, respetando PSR-12.</p><p><strong>4. Desarrollo por fases</strong></p><p>Conserva las fases propuestas, pero actualiza la arquitectura, el árbol de directorios y la documentación para reflejar Composer y Ollama.</p><p>Empezaremos únicamente con:</p><ul><li>Fase 0: infraestructura Docker, PHP 8.4, Composer y configuración del proyecto.</li><li>Fase 1: interfaz inicial del laboratorio con Tailwind CSS y DaisyUI.</li></ul><p>No implementes todavía el servicio de IA ni los formularios funcionales.</p><p>Primero actualiza el plan y muéstrame el árbol de directorios definitivo. Espera mi confirmación antes de crear archivos.</p>",16)])])}const _=a(l,[["render",s]]);export{u as __pageData,_ as default};
